trigger CarrierTrigger on Carrier__c (after insert, after update) {
    List accountID = New List();   
    for(Carrier__c carrierRecord : Trigger.New){
        if(carrierRecord.Account__c != null){
            accountID.add(carrierRecord.Account__c);
        }
    }

    List carrierList = [SELECT Id, Account__c, iDeliver_Portal_url__c, iDeliver_Admin_url__c, Agreement_Type__c FROM Carrier__c WHERE Account__c IN :accountID];
    List accList = [SELECT Id, iDeliver_Portal__c, iDeliver_Admin_Portal__c, Agreement_Type__c FROM Account WHERE Id IN :accountID];
    for(integer i = 0 ; i &lt; accList.size(); i++){
        String iDeliver_Portal_url = ''+carrierList[i].get('iDeliver_Portal_url__c');
        String iDeliver_Admin_url = ''+carrierList[i].get('iDeliver_Admin_url__c');
        String Agreement_Type = ''+carrierList[i].get('Agreement_Type__c');
        accList[i].iDeliver_Portal__c = iDeliver_Portal_url;
        accList[i].iDeliver_Admin_Portal__c = iDeliver_Admin_url;
        accList[i].Agreement_Type__c = Agreement_Type;
    }
    update accList;

